INSERT INTO menu.menu_items (id, category_id, name, description, image_url, base_price, station, is_available, is_featured, is_active, created_at, updated_at) VALUES ('83ce7872-84ea-4f1d-82fe-9ce24a045976', '3963dfaa-9551-4bef-972c-46d366f71822', 'Bánh Mì Chảo', 'Bánh mì chảo với xúc xích, pate gan, trứng ốp la lòng đào béo ngậy, ăn kèm bánh mì nóng giòn tan.', 'https://images.unsplash.com/photo-1578985545062-69928b1d9587', 55000, 'HOT', true, false, true, now(), now());
INSERT INTO menu.menu_items (id, category_id, name, description, image_url, base_price, station, is_available, is_featured, is_active, created_at, updated_at) VALUES ('9a1658a2-90a8-431e-bf47-3ad91eaaf9c1', 'c0f106ed-0de0-483f-a30f-20f4f86c5752', 'Khoai Tây Chiên', 'Khoai tây chiên giòn rụm, phủ lớp muối tỏi mỏng, ăn kèm với tương ớt và mayonnaise phô mai.', 'https://images.unsplash.com/photo-1600271886742-f049cd451bba', 35000, 'HOT', true, true, true, now(), now());
INSERT INTO menu.menu_items (id, category_id, name, description, image_url, base_price, station, is_available, is_featured, is_active, created_at, updated_at) VALUES ('59be1713-b9c8-495f-8689-cc3bab94f225', '2f66ba07-30a0-4f5e-a0e5-164d305d9464', 'Gà Rán Phần', 'Gà rán nguyên bản với lớp vỏ giòn tan bọc ngoài lớp thịt mềm mọng nước, tẩm ướp đậm đà.', 'https://images.unsplash.com/photo-1565299624946-b28f40a0ae38', 25000, 'HOT', true, false, true, now(), now());
INSERT INTO menu.menu_items (id, category_id, name, description, image_url, base_price, station, is_available, is_featured, is_active, created_at, updated_at) VALUES ('093a748f-7bc0-4d97-bc9e-cafb28218d60', 'ee790709-4f7e-43b8-a69b-e39cdbca4902', 'Cà Phê Trứng Nóng', 'Sự kết hợp hoàn hảo giữa vị đắng của cà phê Robusta và lớp kem trứng đánh bông béo ngậy, ngọt ngào.', 'https://images.unsplash.com/photo-1541658016709-815cefac15f2', 25000, 'HOT', true, true, true, now(), now());
INSERT INTO menu.menu_items (id, category_id, name, description, image_url, base_price, station, is_available, is_featured, is_active, created_at, updated_at) VALUES ('1295b18a-2fe0-42d7-84ea-2d2b8f506ce5', '2f66ba07-30a0-4f5e-a0e5-164d305d9464', 'Trà Gừng Nóng', 'Trà gừng sả tắc ấm nóng, tốt cho sức khỏe, giải cảm cực kỳ hiệu quả.', 'https://images.unsplash.com/photo-1556679343-c7306c1976bc', 55000, 'HOT', true, true, true, now(), now());
INSERT INTO menu.menu_items (id, category_id, name, description, image_url, base_price, station, is_available, is_featured, is_active, created_at, updated_at) VALUES ('8c330c7b-b442-4454-b2d4-f92ff02fffc9', '2f66ba07-30a0-4f5e-a0e5-164d305d9464', 'Bánh Mì Quế', 'Bánh mì cuộn quế thơm lừng, phủ lớp kem phô mai béo mịn đặc trưng.', 'https://images.unsplash.com/photo-1556679343-c7306c1976bc', 35000, 'HOT', true, false, true, now(), now());
INSERT INTO menu.menu_items (id, category_id, name, description, image_url, base_price, station, is_available, is_featured, is_active, created_at, updated_at) VALUES ('77d3ca3d-99d4-4dd4-9147-d1ae5acf98bc', '7500b65a-422d-4560-af02-af0414855d6a', 'Soup Cà Chua', 'Súp cà chua thịt bằm nóng hổi, ăn kèm với bánh mì nướng tỏi bơ thơm nức mũi.', 'https://images.unsplash.com/photo-1578985545062-69928b1d9587', 45000, 'HOT', true, false, true, now(), now());
INSERT INTO menu.menu_items (id, category_id, name, description, image_url, base_price, station, is_available, is_featured, is_active, created_at, updated_at) VALUES ('68ebfbc1-e7a7-4ac6-a517-cc6226527518', 'ee790709-4f7e-43b8-a69b-e39cdbca4902', 'Sandwich Nướng', 'Sandwich nướng kẹp dăm bông và phô mai chảy nóng hổi, bữa sáng nhanh gọn hoàn hảo.', 'https://images.unsplash.com/photo-1559525839-b184a4d698c7', 65000, 'HOT', true, false, true, now(), now());
INSERT INTO menu.menu_items (id, category_id, name, description, image_url, base_price, station, is_available, is_featured, is_active, created_at, updated_at) VALUES ('4a27d9f6-6bec-4381-a226-5020294f349a', 'c0f106ed-0de0-483f-a30f-20f4f86c5752', 'Pizza Mini', 'Pizza size nhỏ ngập tràn phô mai Mozzarella, xúc xích và sốt cà chua tươi.', 'https://images.unsplash.com/photo-1565299624946-b28f40a0ae38', 25000, 'HOT', true, false, true, now(), now());
INSERT INTO menu.menu_items (id, category_id, name, description, image_url, base_price, station, is_available, is_featured, is_active, created_at, updated_at) VALUES ('40e2c72e-69ec-48ca-8ae6-451dae2d9598', '9a4982fc-a2d4-462f-83f2-b74474c278e3', 'Trà Sen Vàng Nóng', 'Trà ô long thanh mát kết hợp cùng hạt sen bùi bùi và lớp kem macchiato nóng béo ngậy.', 'https://images.unsplash.com/photo-1565299624946-b28f40a0ae38', 65000, 'HOT', true, false, true, now(), now());
INSERT INTO menu.menu_items (id, category_id, name, description, image_url, base_price, station, is_available, is_featured, is_active, created_at, updated_at) VALUES ('0c6e0670-f4cb-4519-b83d-d130406ee88f', '9a4982fc-a2d4-462f-83f2-b74474c278e3', 'Cacao Nóng', 'Cacao nguyên chất pha sữa nóng ấm áp, lựa chọn tuyệt vời cho những ngày se lạnh.', 'https://images.unsplash.com/photo-1541658016709-815cefac15f2', 45000, 'HOT', true, false, true, now(), now());
