INSERT INTO menu.menu_items (id, category_id, name, description, image_url, base_price, station, is_available, is_featured, is_active, created_at, updated_at) VALUES ('f2aba607-8119-4610-9286-33bd39784f3f', '3963dfaa-9551-4bef-972c-46d366f71822', 'Hồng Trà Sữa Nóng', 'Hồng trà sữa nấu theo công thức hoàng gia, ấm nóng và thoang thoảng mùi lá trà sấy.', 'https://images.unsplash.com/photo-1559525839-b184a4d698c7', 55000, 'HOT', true, false, true, now(), now());
INSERT INTO menu.menu_items (id, category_id, name, description, image_url, base_price, station, is_available, is_featured, is_active, created_at, updated_at) VALUES ('f59cbc8d-8709-4194-9681-979f0b4d852f', 'ee790709-4f7e-43b8-a69b-e39cdbca4902', 'Tiramisu', 'Bánh Tiramisu Ý truyền thống mềm mịn, hòa quyện hương vị cà phê Espresso và phô mai Mascarpone béo ngậy.', 'https://images.unsplash.com/photo-1541658016709-815cefac15f2', 55000, 'COLD', true, false, true, now(), now());
